namespace ghidra.util.timer;

using static org.junit.Assert;



using org.junit;

using generic.test;
using ghidra.util;

public class WatchdogTest : AbstractGTest {

	/* @Test(timeout = 20000) */
	public void test() {
		long watchdogTimeoutMS = 10;

		// watchdog could take N*2 to trigger
		long watchdogMaxIntrMS = watchdogTimeoutMS * 3;
		AtomicBoolean inerruptedFlag = new AtomicBoolean();

		Thread testThread = Thread.currentThread();
		using (Watchdog watchDog = new Watchdog(watchdogTimeoutMS, () => {
			Msg.trace(this, "" + DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() + ": Interrupting the test thread..."))
using (inerruptedFlag.set(true))
using (testThread.interrupt())
using (}))
{

			for (int i = 0; i < 10; i++) {
				inerruptedFlag.set(false);
				watchDog.arm();
				long start = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
				try {
					Thread.sleep(DEFAULT_WAIT_TIMEOUT);
					fail(DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() + ": Watchdog did not fire");
				}
				catch (InterruptedException e) {
					assertTrue("" + DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() +
						": Sleep was interrupted, but not by watchdog", inerruptedFlag.get());
					long elapsed = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() - start;
					Msg.trace(this, DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() + ": Watchdog fired in: " + elapsed +
						"ms, max target is: " + watchdogMaxIntrMS + "ms");
				}
			}
		}

	}

}
